#!/usr/bin/env bash
set -euo pipefail

# The report is generated by an embedded Python script.
command -v python3 >/dev/null 2>&1 || { echo "Error: python3 not found"; exit 1; }

RESULTS_DIR="${1:?Usage: report.sh <results-dir>}"

if [ ! -d "${RESULTS_DIR}" ]; then
  echo "Error: ${RESULTS_DIR} does not exist"
  exit 1
fi

export RESULTS_DIR
BRANCH=$(git rev-parse --abbrev-ref HEAD 2>/dev/null || echo "unknown")
COMMIT=$(git rev-parse --short HEAD 2>/dev/null || echo "unknown")
export BRANCH COMMIT

# Auto-detect scenario from results directory contents
if [ -f "${RESULTS_DIR}/ai-baseline-run1.json" ]; then
  export CONFIGS="ai-baseline ai-otel-noop ai-otel-full"
  export BASELINE_LABEL="AI Baseline"
  export NOOP_LABEL="AI OTel (noop)"
  export FULL_LABEL="AI OTel (full)"
  export REPORT_TITLE="Praxis AI OTel Overhead Benchmark"
  export BACKEND_DESC="inference-sim (mock LLM)"
else
  export CONFIGS="baseline otel-noop otel-full"
  export BASELINE_LABEL="Baseline"
  export NOOP_LABEL="OTel (noop)"
  export FULL_LABEL="OTel (full)"
  export REPORT_TITLE="Praxis OTel Overhead Benchmark"
  export BACKEND_DESC="Fortio echo"
fi

REPORT="${RESULTS_DIR}/report.md"

# Use Python to generate the report (macOS has bash 3.2, no associative arrays)
python3 << 'PYTHON_SCRIPT'
import json
import statistics
import glob
import sys
import os
from datetime import datetime

results_dir = os.environ['RESULTS_DIR']
branch = os.environ['BRANCH']
commit = os.environ['COMMIT']
configs = os.environ['CONFIGS'].split()
baseline_label = os.environ['BASELINE_LABEL']
noop_label = os.environ['NOOP_LABEL']
full_label = os.environ['FULL_LABEL']
report_title = os.environ['REPORT_TITLE']
backend_desc = os.environ['BACKEND_DESC']

baseline_config, noop_config, full_config = configs
stats = {}

# Aggregate with the MEDIAN, not the mean. The first run against a freshly
# rolled pod pays OTLP exporter connection setup and JIT-warm costs that no
# realistic 10s warmup covers -- one such run has been observed at a 27ms P99
# against a ~1.7ms steady state. A mean lets that single run dominate and
# reports a ~500% regression that does not exist; a median over the configured
# run count is robust to it. The per-run P99 range is reported alongside so an
# outlier stays visible instead of being silently smoothed away.
for config in configs:
    p50s, p99s, rpss = [], [], []

    pattern = os.path.join(results_dir, f'{config}-run*.json')
    for path in glob.glob(pattern):
        try:
            with open(path) as f:
                data = json.load(f)
                p50s.append(data['latencies']['50th'])
                p99s.append(data['latencies']['99th'])
                rpss.append(data['throughput'])
        except (json.JSONDecodeError, KeyError) as e:
            print(f"Warning: Failed to parse {path}: {e}", file=sys.stderr)
            continue

    if p50s:
        stats[config] = {
            'p50': int(statistics.median(p50s) / 1000),  # nanoseconds -> microseconds
            'p99': int(statistics.median(p99s) / 1000),
            'p99_min': int(min(p99s) / 1000),
            'p99_max': int(max(p99s) / 1000),
            'rps': int(statistics.median(rpss)),
            'runs': len(p50s)
        }
    else:
        stats[config] = {'p50': 0, 'p99': 0, 'p99_min': 0, 'p99_max': 0, 'rps': 0, 'runs': 0}

# Generate report
report_path = os.path.join(results_dir, 'report.md')
with open(report_path, 'w') as f:
    f.write(f"# {report_title}\n\n")
    f.write(f"**Date:** {datetime.now().strftime('%Y-%m-%d')} | **Commit:** {commit} | **Branch:** {branch}\n")
    f.write(f"**Platform:** KIND (1 node) | **Backend:** {backend_desc}\n\n")

    # Scenario block, read back from what the run actually recorded rather
    # than restated here, so the report cannot drift from the configs.
    scen_path = os.path.join(results_dir, 'scenario.env')
    if os.path.exists(scen_path):
        scen = {}
        with open(scen_path) as sf:
            for raw in sf:
                if '=' in raw:
                    key, _, val = raw.strip().partition('=')
                    scen[key] = val
        f.write("## Scenario\n\n")
        f.write(f"`{scen.get('rate', '?')}` RPS x `{scen.get('duration', '?')}` "
                f"x `{scen.get('runs', '?')}` runs per config, "
                f"`{scen.get('connections', '?')}` connections.\n\n")
        f.write("| Run | Config | Cargo features | Trace sampling | Filter chain |\n")
        f.write("| --- | --- | --- | --- | --- |\n")
        for letter in ('A', 'B', 'C'):
            label = scen.get(f'run.{letter}.label', '')
            if not label:
                continue
            feats = scen.get(f'run.{letter}.features') or 'none'
            filters = scen.get(f'run.{letter}.filters', '').replace(',', ' -> ')
            samp = scen.get(f'run.{letter}.sampling') or 'AlwaysOn'
            f.write(f"| {letter} ({label}) | `{scen.get(f'run.{letter}.config', '')}` | "
                    f"`{feats}` | `{samp}` | {filters} |\n")
        f.write("\n")

    f.write(f"## Summary\n\n")
    f.write(f"| Config | P50 (us) | P99 (us) | P99 range (us) | RPS | Runs | P50 delta | P99 delta |\n")
    f.write(f"| --- | --- | --- | --- | --- | --- | --- | --- |\n")

    base_p50 = stats[baseline_config]['p50']
    base_p99 = stats[baseline_config]['p99']

    for config in configs:
        s = stats[config]
        p50 = s['p50']
        p99 = s['p99']
        rps = s['rps']
        runs = s['runs']
        p99_range = f"{s['p99_min']}-{s['p99_max']}"

        if config == baseline_config:
            f.write(f"| {baseline_label} | {p50} | {p99} | {p99_range} | {rps} | {runs} | -- | -- |\n")
        else:
            label = noop_label if config == noop_config else full_label

            if base_p50 > 0:
                dp50 = f"{(p50 - base_p50) / base_p50 * 100:+.1f}%"
                dp99 = f"{(p99 - base_p99) / base_p99 * 100:+.1f}%"
            else:
                dp50 = "N/A"
                dp99 = "N/A"

            f.write(f"| {label} | {p50} | {p99} | {p99_range} | {rps} | {runs} | {dp50} | {dp99} |\n")

print(f"Report written to: {report_path}")
PYTHON_SCRIPT

echo ""
cat "${REPORT}"
